'use strict';
const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
let world,building=null,detail=4,view,baseView,drag=null,moved=false,lastFocus;
const svg=$('map');
function el(tag,attrs={},parent=svg,text){const n=document.createElementNS(NS,tag);for(const [k,v]of Object.entries(attrs))if(v!==undefined)n.setAttribute(k,v);if(text!==undefined)n.textContent=text;parent.append(n);return n}
const pts=a=>(a||[]).map(p=>`${p[0]},${-p[1]}`).join(' ');
function poly(a,fill,stroke='#64744b',sw=.35,parent=svg){return el('polygon',{points:pts(a),fill,stroke,'stroke-width':sw,'stroke-linejoin':'round'},parent)}
function line(a,color,width,parent=svg,extra={}){return el('polyline',{points:pts(a),fill:'none',stroke:color,'stroke-width':width,'stroke-linecap':'round','stroke-linejoin':'round',...extra},parent)}
function bounds(a){let xs=a.map(p=>p[0]),ys=a.map(p=>p[1]);return{x:Math.min(...xs),y:Math.min(...ys),w:Math.max(...xs)-Math.min(...xs),h:Math.max(...ys)-Math.min(...ys)}}
function center(a){const b=bounds(a);return[b.x+b.w/2,b.y+b.h/2]}
function txt(x,y,t,size=2.4,parent=svg,attrs={}){return el('text',{x,y:-y,'text-anchor':'middle','font-size':size,...attrs},parent,t)}
function interactive(node,name,fn){node.classList.add('map-object');node.setAttribute('tabindex','0');node.setAttribute('role','button');node.setAttribute('aria-label',name);node.addEventListener('click',e=>{if(!moved){e.stopPropagation();fn()}});node.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn()}})}
function setView(v){view=v;svg.setAttribute('viewBox',`${v.x} ${v.y} ${v.w} ${v.h}`)}
function fit(){let b=building?bounds(building.polygon):{x:0,y:0,w:world.bounds.width,h:world.bounds.depth};let pad=building?Math.max(b.w,b.h)*.08:12;let w=b.w+pad*2,h=b.h+pad*2;let aspect=svg.clientWidth/svg.clientHeight;if(w/h>aspect)h=w/aspect;else w=h*aspect;let cx=b.x+b.w/2,cy=-(b.y+b.h/2);baseView={x:cx-w/2,y:cy-h/2,w,h};setView({...baseView})}
function zoom(f){let w=view.w*f,h=view.h*f;if(w<5||w>600)return;setView({x:view.x+(view.w-w)/2,y:view.y+(view.h-h)/2,w,h})}
function open(title,kicker='FIELD NOTES'){lastFocus=document.activeElement;$('drawer-title').textContent=title;$('drawer-kicker').textContent=kicker;$('drawer-content').replaceChildren();$('drawer').hidden=false;$('scrim').hidden=false;$('close').focus();return $('drawer-content')}
function close(){$('drawer').hidden=true;$('scrim').hidden=true;lastFocus?.focus()}
function html(tag,text,parent,cls){const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;parent.append(n);return n}
function card(parent,title,desc,fn){let c=html(fn?'button':'div',null,parent,'card');html('strong',title,c);if(desc)html('small',desc,c);if(fn)c.onclick=fn;return c}
function describe(v){if(v==null)return '';if(typeof v==='string')return v;if(typeof v==='number'||typeof v==='boolean')return String(v);if(Array.isArray(v))return v.map(describe).join(' · ');return Object.entries(v).map(([k,x])=>`${k.replaceAll('_',' ')}: ${describe(x)}`).join('; ')}
function roomPanel(r){const p=open(r.name,'INSIDE '+building.name.toUpperCase());html('p',r.description,p);if(r.finishes)card(p,'Materials',describe(r.finishes));if(r.designIntent)card(p,'Why this arrangement',r.designIntent);if(r.lighting)card(p,'Light',describe(r.lighting));for(const win of r.windows||[])card(p,win.name,`${win.width} m wide · sill ${win.sillHeight} m above floor`);html('span',`${(r.contents||[]).length} specified objects`,p,'badge');html('span',`${(r.doors||[]).length} door connections`,p,'badge');for(const o of r.contents||[])card(p,o.name,`${o.kind||'Object'} · ${o.size?o.size.join(' × ')+' m':''}`,()=>objectPanel(o,r));if(!r.contents?.length)html('p','No contents have been specified for this room yet.',p)}
function objectPanel(o,r){const p=open(o.name,r.name.toUpperCase());html('p',o.description,p);card(p,'Condition & state',describe(o.state)||'Not specified');if(o.material)card(p,'Material',o.material);if(o.location)card(p,'Stored here',o.location);if(o.inventory?.length){html('h3',`${o.inventory.length} contents · inspect each`,p);for(const child of o.inventory)card(p,child.name,child.location,()=>objectPanel(child,r));html('p','Inventory symbols and compartment descriptions are schematic; individual contents do not yet have validated 3D placement.',p,'meta');}card(p,'Possible interactions',describe(o.affordances)||'Not specified');html('p','These are authored interaction specifications. This viewer does not execute a first-person simulation.',p,'meta');if(o.position)card(p,'Position',`East ${o.position[0]} m · north ${o.position[1]} m · height ${o.position[2]||0} m`);const back=html('button','← All objects in '+r.name,p,'action');back.onclick=()=>roomPanel(r)}
function enter(b){building=b;close();$('back').hidden=false;$('eyebrow').textContent='ROOMS · CONTENTS · EVERYDAY LIFE';$('scene-title').textContent=b.name;$('hint').textContent='Tap a room or an object to discover its story.';render();fit();$('rooms').classList.add('active');$('land').classList.remove('active')}
function site(){building=null;close();$('back').hidden=true;$('eyebrow').textContent='NEW ENGLAND · NO-KILL HOMESTEAD';$('scene-title').textContent='A little world, rooted here.';$('hint').textContent='Follow the brook. Step inside the red barn.';render();fit();$('land').classList.add('active');$('rooms').classList.remove('active')}
function tree(v){let [x,y]=v.position||[0,0],r=v.radius||v.canopyRadius||2;const g=el('g');el('ellipse',{cx:x+r*.25,cy:-y+r*.3,rx:r,ry:r*.8,fill:'#31583d',opacity:.16},g);let species=(v.kind+' '+v.species).toLowerCase();if(/wildflower|grass|groundcover|fern/.test(species)){for(let i=0;i<7;i++){let a=i*2.4,dx=Math.cos(a)*r*.65,dy=Math.sin(a)*r*.65;line([[x+dx,y+dy],[x+dx+.15,y+dy+.5]],'#7d9c58',.15,g);if(i%2===0)el('circle',{cx:x+dx+.15,cy:-(y+dy+.5),r:.22,fill:i%3===0?'#e6ce7c':'#f2e6c1'},g)}}else if(/pine|hemlock|conifer|spruce|fir/.test(species)){poly([[x,y+r*1.3],[x-r*.8,y-r*.7],[x+r*.8,y-r*.7]],'#45664b','#344e3b',.28,g);poly([[x,y+r*1.3],[x,y-r*.7],[x-r*.8,y-r*.7]],'#5f8155','none',0,g);line([[x,y-r*.7],[x,y-r]],'#695839',.4,g)}else{let shrub=/shrub|fern|berry|bush/.test(species),col=shrub?'#8caa60':'#6f9350';let a=Array.from({length:7},(_,i)=>{let ang=i*Math.PI*2/7;return[x+Math.cos(ang)*r,y+Math.sin(ang)*r]});poly(a,col,'#526b42',.22,g);poly([[x-r*.8,y+r*.25],[x-r*.2,y+r*.9],[x+r*.5,y+r*.5],[x+r*.2,y-r*.1],[x-r*.4,y-r*.2]],shrub?'#a7bd70':'#93ad65','none',0,g);if(detail>=4&&!shrub)line([[x,y-r*.6],[x,y],[x+r*.35,y+r*.35]],'#678249',.15,g)}if(detail>=5)interactive(g,v.species||v.kind,()=>{let p=open(v.species||v.kind,'NATURAL LAYER');html('p',v.description||'A planted or retained part of the authored New England landscape.',p);card(p,'Habitat',describe(v.habitat||v.role||v.ecology));});}
function roof(b){const g=el('g'),a=bounds(b.polygon),red=/barn|annex/.test(b.kind+' '+b.name.toLowerCase()),base=red?'#aa5645':'#b5a47c';poly(b.polygon.map(p=>[p[0]+1,p[1]-1]),'#58744755','none',0,g);poly(b.polygon,base,'#4d5141',.5,g);let mid=a.x+a.w/2;poly([[a.x,a.y],[mid,a.y],[mid,a.y+a.h],[a.x,a.y+a.h]],red?'#c86f54':'#d2bb8c','#6b674f',.25,g);line([[mid,a.y],[mid,a.y+a.h]],red?'#7e4439':'#82765b',.4,g);if(detail>=3){for(let y=a.y+1;y<a.y+a.h;y+=1.5)line([[a.x+.25,y],[mid-.2,y]],red?'#a95c48':'#b9a479',.12,g);poly([[mid-.8,a.y+1],[mid+.8,a.y+1],[mid+.8,a.y+3],[mid-.8,a.y+3]],'#eee7cf','#5c6553',.22,g)}interactive(g,'Explore '+b.name,()=>enter(b));if(detail>=2 && !/annex/.test(b.kind+' '+b.name.toLowerCase()))txt(a.x+a.w/2,a.y-3,red?'RED RESCUE BARN':'FARMHOUSE',3.1,svg,{class:'label'});}
function renderSite(){el('rect',{x:-1000,y:-1000,width:2000,height:2000,fill:'#dce6c8'});const w=world.bounds.width,h=world.bounds.depth;poly([[0,0],[w,0],[w,h],[0,h]],'#b9ce8a','#8ba36a',.5);let grid=world.terrain?.grid;if(grid?.heights&&detail>=2){let vals=grid.heights.flat(),mn=Math.min(...vals),mx=Math.max(...vals);for(let j=0;j<grid.rows-1;j++)for(let i=0;i<grid.cols-1;i++){let z=vals[j*grid.cols+i],spacing=grid.spacing||w/(grid.cols-1),sx=Array.isArray(spacing)?spacing[0]:spacing,sy=Array.isArray(spacing)?spacing[1]:spacing,origin=grid.origin||[0,0],x=origin[0]+i*sx,y=origin[1]+j*sy;el('rect',{x,y:-y-sy,width:sx+.1,height:sy+.1,fill:z>mn+(mx-mn)*.6?'#e3e7a7':'#719d6c',opacity:.035})}}
for(const p of world.parcels||[]){let k=p.kind||'',fill=/veget|garden|crop/.test(k)?'#bfa16b':/paddock/.test(k)?'#becb83':/yard/.test(k)?'#cbd697':'#b1c77d';poly(p.polygon,fill,'#8fa266',.35);if(/veget|garden|crop/.test(k)){const b=bounds(p.polygon),clip=el('clipPath',{id:'clip-'+p.id});poly(p.polygon,'white','none',0,clip);const g=el('g',{'clip-path':`url(#clip-${p.id})`});for(let x=b.x+1;x<b.x+b.w;x+=2){line([[x,b.y],[x,b.y+b.h]],'#e0c18a',.7,g);if(detail>=2)line([[x+.7,b.y],[x+.7,b.y+b.h]],'#64844d',.8,g)}}if(/paddock|pasture/.test(k)){line([...p.polygon,p.polygon[0]],'#716d49',.55);if(detail>=3)for(let i=0;i<p.polygon.length;i++){let a=p.polygon[i],b=p.polygon[(i+1)%p.polygon.length],n=Math.ceil(Math.hypot(b[0]-a[0],b[1]-a[1])/3);for(let j=0;j<n;j++)el('circle',{cx:a[0]+(b[0]-a[0])*j/n,cy:-(a[1]+(b[1]-a[1])*j/n),r:.4,fill:'#f5e8be',stroke:'#78704f','stroke-width':.2})}}}
let brook=world.water?.brook;if(brook){let a=[...(brook.leftBank||[]),...(brook.rightBank||[]).slice().reverse()];if(a.length)poly(a,'#78b8b4','#669b88',.55);else line(brook.centerline,'#76b5ae',brook.width||5);line(brook.centerline,'#c4dfce',.45,svg,{'stroke-dasharray':'2 4',opacity:.75})}
for(let p of world.paths||[]){line(p.points,'#8f9c69',(p.width||1.5)+.8);line(p.points,'#e1c994',p.width||1.5);if(detail>=4)line(p.points,'#eddbaf',.25,svg,{'stroke-dasharray':'.4 2'})}
if(world.bridge?.polygon){poly(world.bridge.polygon,'#b69867','#6b6850',.4);let b=bounds(world.bridge.polygon);for(let y=b.y+.5;y<b.y+b.h;y+=.7)line([[b.x,y],[b.x+b.w,y]],'#7c7254',.13);line([[b.x,b.y],[b.x,b.y+b.h]],'#f2ddb3',.45);line([[b.x+b.w,b.y],[b.x+b.w,b.y+b.h]],'#f2ddb3',.45)}
if(detail>=3)for(const o of world.outdoorContents||[])prop(o,{name:'Out on the land',contents:world.outdoorContents});
for(let v of [...world.vegetation||[]].sort((a,b)=>b.position[1]-a.position[1]))tree(v);
for(let b of world.buildings||[])roof(b);
if(detail>=3)for(let a of world.actors||[]){let pos=a.position||a.initialPosition||a.location;if(!pos)continue;let [x,y]=pos,g=el('g'),kind=(a.kind+' '+a.species).toLowerCase();el('ellipse',{cx:x,cy:-y,rx:/hen|chicken/.test(kind)?.35:.7,ry:/hen|chicken/.test(kind)?.45:1,fill:/human|person/.test(kind)?'#c17a50':'#f9f2d9',stroke:'#687052','stroke-width':.2},g);interactive(g,a.name,()=>{let p=open(a.name,'LIFE ON THE RANCH');html('p',a.description,p);card(p,'Daily life',describe(a.routine||a.needs||a.activities));})}
if(detail>=2)for(let p of world.parcels||[]){if(!/veget|garden|crop/.test(p.kind))continue;let c=center(p.polygon);txt(c[0],c[1],'KITCHEN GARDEN',2.5,svg,{class:'label'})}
}
function prop(o,r){if(!o.position)return;let [w,d]=o.size||[.7,.7],x=o.position[0]+w/2,y=o.position[1]+d/2,g=el('g',{transform:`translate(${x} ${-y}) rotate(${-(o.rotation||0)})`});let kind=(o.kind+' '+o.name).toLowerCase(),fill=/bed|sofa|chair/.test(kind)?'#d3b17b':/water|sink|trough|bath/.test(kind)?'#83bcb4':/feed|hay|straw|bale|resting/.test(kind)?'#d4ba65':/tool|equipment/.test(kind)?'#7d9180':'#b69267';el('rect',{x:-w/2,y:-d/2,width:w,height:d,rx:Math.min(w,d)*.12,fill,stroke:'#655f49','stroke-width':.055},g);if(/bed/.test(kind)&&!/resting|bedding/.test(kind)){el('rect',{x:-w*.4,y:-d*.43,width:w*.8,height:d*.22,rx:.08,fill:'#fbf1d9'},g);line([[-w*.45,-d*.15],[w*.45,-d*.15]],'#a57954',.05,g)}else if(/table|desk/.test(kind)){el('rect',{x:-w*.35,y:-d*.3,width:w*.24,height:d*.4,fill:'#f0e4c2'},g)}else if(/hay|feed|straw|bale|resting/.test(kind)){for(let i=-1;i<2;i++)line([[i*w/4,-d*.4],[i*w/4,d*.4]],'#9d8745',.04,g)}else if(/bucket|bowl|basin|trough/.test(kind)){el('ellipse',{cx:0,cy:0,rx:w*.38,ry:d*.38,fill:'#94bcb1',stroke:'#527668','stroke-width':.07},g);el('ellipse',{cx:0,cy:0,rx:w*.24,ry:d*.24,fill:'#c9ded0'},g)}else if(/wheelbarrow/.test(kind)){poly([[-w*.4,-d*.2],[w*.4,-d*.2],[w*.3,d*.25],[-w*.3,d*.25]],'#6f9282','#516b5d',.04,g);line([[-w*.25,d*.25],[-w*.25,d*.47]],'#6c654b',.07,g);line([[w*.25,d*.25],[w*.25,d*.47]],'#6c654b',.07,g);el('circle',{cx:0,cy:-d*.4,r:w*.16,fill:'#4b5748'},g)}else if(/rack|tools/.test(kind)){for(let i=-1;i<2;i++){line([[i*w*.25,-d*.4],[i*w*.25,d*.4]],'#e1c38c',.07,g);line([[i*w*.25-w*.1,d*.35],[i*w*.25+w*.1,d*.35]],'#66796b',.09,g)}}else if(/stove|range/.test(kind)){for(let a of [-1,1])for(let b of [-1,1])el('circle',{cx:a*w*.23,cy:b*d*.23,r:Math.min(w,d)*.15,fill:'#536456'},g)}else if(/plant|flower/.test(kind)){el('circle',{cx:0,cy:0,r:Math.min(w,d)*.38,fill:'#789253'},g)}if(detail>=4&&o.inventory?.length){let n=Math.min(o.inventory.length,6);for(let i=0;i<n;i++){let cx=-w*.32+(i%3)*w*.32,cy=-d*.2+Math.floor(i/3)*d*.4;el('rect',{x:cx-w*.07,y:cy-d*.08,width:w*.14,height:d*.16,rx:.025,fill:i%2?'#e7d6a4':'#7c9b82',stroke:'#6e7055','stroke-width':.025},g)}}interactive(g,o.name+(o.inventory?.length?' · '+o.inventory.length+' contents':''),()=>objectPanel(o,r));}
function renderBuilding(){el('rect',{x:-1000,y:-1000,width:2000,height:2000,fill:'#e7ead8'});poly(building.polygon.map(p=>[p[0]+.3,p[1]-.3]),'#a8b18c','none');poly(building.polygon,'#f4e6c9','#52604a',.32);for(const r of building.rooms||[]){const g=el('g');poly(r.polygon,/stall|animal/.test(r.kind+' '+r.name.toLowerCase())?'#d7c795':'#eee0be','#776d52',.16,g);interactive(g,'Inspect '+r.name,()=>roomPanel(r));let b=bounds(r.polygon);if(detail>=4&&r.finishes){let tile=/tile|slab|concrete/.test(r.finishes.floor);if(tile){for(let x=b.x+.5;x<b.x+b.w;x+=.65)line([[x,b.y+.12],[x,b.y+b.h-.12]],'#a69e7838',.025,g)}}for(let y=b.y+.5;y<b.y+b.h;y+=.65)line([[b.x+.12,y],[b.x+b.w-.12,y]],'#bfac8528',.035,g);if(detail>=3)for(const win of r.windows||[]){let [x,y]=win.position,h=win.width/2;line(win.orientation==='horizontal'?[[x-h,y],[x+h,y]]:[[x,y-h],[x,y+h]],'#639b9b',.25);line(win.orientation==='horizontal'?[[x-h,y],[x+h,y]]:[[x,y-h],[x,y+h]],'#d5f1e7',.09);}if(detail>=2)for(let o of r.contents||[])prop(o,r);let c=center(r.polygon);txt(c[0],b.y+b.h-.5,r.name,Math.min(.5,b.w/Math.max(r.name.length,1)*1.3),svg,{class:'label','stroke-width':.10});for(let d of r.doors||[]){let p=d.position;if(!p)continue;let vertical=Math.abs(p[0]-b.x)<.05||Math.abs(p[0]-b.x-b.w)<.05,half=(d.width||.9)/2;line(vertical?[[p[0],p[1]-half],[p[0],p[1]+half]]:[[p[0]-half,p[1]],[p[0]+half,p[1]]],'#f8efdb',.23);}}
}
function render(){svg.classList.toggle('interior',!!building);svg.replaceChildren();building?renderBuilding():renderSite()}
function buildingsPanel(){const p=open('Come on inside','BUILDINGS & ROOMS');for(let b of world.buildings)card(p,b.name,`${b.rooms?.length||0} rooms · ${b.rooms?.reduce((s,r)=>s+(r.contents?.length||0),0)||0} specified objects`,()=>enter(b));html('p','The plans use the same authored world coordinates as the landscape. Tap any room to inspect every declared object.',p)}
function notes(){const p=open('A ranch with a reason','ABBY & ANI’S FIELD NOTES');html('p',world.description||'A no-kill New England homestead tucked into a forest clearing, with a brook at the back and a small bridge leading onward.',p);card(p,'One authored place','This is a specific structured ranch, not a live AI generator. All plans read the same scene JSON.');for(const k of ['operations','unknowns']){let a=world[k];if(a){html('h3',k==='unknowns'?'Open decisions':'Life & care',p);for(let x of Array.isArray(a)?a:[a])card(p,x.name||x.id||'Note',describe(x.description||x.summary||x));}}let dl=html('a','Download the complete ranch JSON',p,'quiet');dl.href='./ranch.json';dl.download='abby-ani-ranch.json';let old=html('a','Open the earlier procedural layout study ↗',p,'quiet');old.href='./ranch.html';}
$('close').onclick=close;$('scrim').onclick=close;$('back').onclick=site;$('land').onclick=()=>world&&site();$('rooms').onclick=()=>world&&buildingsPanel();$('journal').onclick=()=>world&&notes();$('about').onclick=()=>world&&notes();$('zoom-in').onclick=()=>zoom(.8);$('zoom-out').onclick=()=>zoom(1.25);$('fit').onclick=()=>world&&fit();$('layers').onclick=()=>{const p=open('How closely shall we look?','PRESENTATION DETAIL');['Overland silhouette','Parcels & buildings','Rooms & everyday life','Materials & small traces','Inspectable specification'].forEach((name,i)=>{let c=card(p,`${i+1} · ${name}`,i===4?'Displays the deepest available authored data; not first-person gameplay.':null,()=>{detail=i+1;render();close()});if(detail===i+1)c.classList.add('chosen')});html('p','These filters reveal the available scene. They do not fabricate additional objects. Ultra refinement is not running in this viewer.',p)};
const pointers=new Map();let pinch=null;
function beginPinch(){const a=[...pointers.values()],rect=svg.getBoundingClientRect(),cx=(a[0][0]+a[1][0])/2,cy=(a[0][1]+a[1][1])/2;pinch={distance:Math.max(1,Math.hypot(a[1][0]-a[0][0],a[1][1]-a[0][1])),v:{...view},anchor:[view.x+(cx-rect.left)*view.w/rect.width,view.y+(cy-rect.top)*view.h/rect.height]};moved=true;drag=null;for(const id of pointers.keys())svg.setPointerCapture(id);}
svg.addEventListener('pointerdown',e=>{if(!view)return;pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===2)beginPinch();else if(pointers.size===1){drag={x:e.clientX,y:e.clientY,v:{...view},id:e.pointerId};moved=false;}});
svg.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===2&&pinch){const a=[...pointers.values()],rect=svg.getBoundingClientRect(),dist=Math.max(1,Math.hypot(a[1][0]-a[0][0],a[1][1]-a[0][1])),w=Math.max(5,Math.min(600,pinch.v.w*pinch.distance/dist)),h=w*rect.height/rect.width,cx=(a[0][0]+a[1][0])/2,cy=(a[0][1]+a[1][1])/2;setView({x:pinch.anchor[0]-(cx-rect.left)*w/rect.width,y:pinch.anchor[1]-(cy-rect.top)*h/rect.height,w,h});return;}if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(moved||Math.hypot(dx,dy)>5){moved=true;svg.setPointerCapture(e.pointerId);setView({...drag.v,x:drag.v.x-dx*drag.v.w/svg.clientWidth,y:drag.v.y-dy*drag.v.h/svg.clientHeight});}});
function endPointer(e){if(!pointers.has(e.pointerId))return;const wasPinch=!!pinch;pointers.delete(e.pointerId);if(svg.hasPointerCapture(e.pointerId))svg.releasePointerCapture(e.pointerId);pinch=null;drag=null;if(wasPinch)moved=true;if(pointers.size===1){const [id,p]=[...pointers.entries()][0];drag={x:p[0],y:p[1],v:{...view},id};}}
for(const name of ['pointerup','pointercancel'])window.addEventListener(name,endPointer);
svg.addEventListener('lostpointercapture',e=>{if(e.target===svg&&!svg.hasPointerCapture(e.pointerId))endPointer(e);});
svg.addEventListener('dragstart',e=>e.preventDefault());
function preserveCameraOnResize(){if(!world||!view)return;const cx=view.x+view.w/2,cy=view.y+view.h/2,h=view.w*svg.clientHeight/svg.clientWidth;setView({x:cx-view.w/2,y:cy-h/2,w:view.w,h});if(pointers.size===2)beginPinch();else if(pointers.size===1){const[id,p]=[...pointers.entries()][0];drag={x:p[0],y:p[1],v:{...view},id};}}
svg.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.1:.9)},{passive:false});window.addEventListener('resize',preserveCameraOnResize);document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'&&!$('drawer').hidden){let ns=[...$('drawer').querySelectorAll('button,a,[tabindex="0"]')];if(e.shiftKey&&document.activeElement===ns[0]){e.preventDefault();ns.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===ns.at(-1)){e.preventDefault();ns[0].focus()}}});
if(!document.body.hasAttribute('data-procedural'))fetch('./ranch.json').then(r=>{if(!r.ok)throw Error(`Scene request failed (${r.status})`);return r.json()}).then(data=>{world=data;if(!world.bounds||!world.buildings)throw Error('The scene is missing its bounds or buildings.');site()}).catch(e=>{$('hint').textContent='The authored scene could not be loaded.';$('status').textContent=e.message;});

window.RanchView?.register('ranchMap',()=>({selectedBuilding:building?.id||building?.name||building,detail,view,world:world?{seed:world.seed,grown:world.grown,buildings:world.buildings?.map(b=>({id:b.id,name:b.name}))}:null}));
